// Кириллический шрифт для PDF-инструкции (DejaVu Sans, subset Latin+Cyrillic+пунктуация).
// Регистрируется в jsPDF, чтобы русский текст отображался корректно.
(function () {
  if (!window.jspdf || !window.jspdf.jsPDF) return;
  var API = window.jspdf.jsPDF.API;
  var REGULAR = "";
  var BOLD = "";
  API.events.push(["addFonts", function () {
    this.addFileToVFS("DejaVuSans.ttf", REGULAR);
    this.addFont("DejaVuSans.ttf", "DejaVuSans", "normal");
    this.addFileToVFS("DejaVuSans-Bold.ttf", BOLD);
    this.addFont("DejaVuSans-Bold.ttf", "DejaVuSans", "bold");
  }]);
})();
